after:
:root {
  --bg: #f5f5f4;
  --card: #ffffff;
  --text: #1c1917;
  --muted: #78716c;
  --border: #e7e5e4;
  --accent: #2563eb;
  --danger: #dc2626;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1c1917;
    --card: #292524;
    --text: #f5f5f4;
    --muted: #a8a29e;
    --border: #44403c;
    --accent: #60a5fa;
    --danger: #f87171;
  }
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.5 system-ui, -apple-system, sans-serif;
}

.app {
  max-width: 480px;
  margin: 48px auto;
  padding: 24px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
}

h1 { margin: 0 0 16px; font-size: 1.5rem; }

#todo-form { display: flex; gap: 8px; }

#todo-input {
  flex: 1;
  padding: 10px 12px;
  font: inherit;
  color: inherit;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 8px;
}

#todo-input:focus { outline: 2px solid var(--accent); outline-offset: -1px; }

button {
  font: inherit;
  cursor: pointer;
  border: none;
  border-radius: 8px;
}

#todo-form button {
  padding: 10px 16px;
  background: var(--accent);
  color: #fff;
}

#todo-list { list-style: none; margin: 16px 0 0; padding: 0; }

.todo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 4px;
  border-bottom: 1px solid var(--border);
}

.todo label { flex: 1; display: flex; align-items: center; gap: 10px; cursor: pointer; }

.todo input[type="checkbox"] { width: 18px; height: 18px; accent-color: var(--accent); }

.todo.done span { text-decoration: line-through; color: var(--muted); }

.delete {
  padding: 4px 8px;
  background: transparent;
  color: var(--danger);
  opacity: 0;
}

.todo:hover .delete,
.delete:focus-visible { opacity: 1; }

@media (hover: none) { .delete { opacity: 1; } }

.empty { margin: 16px 0 0; color: var(--muted); text-align: center; }
.empty[hidden] { display: none; }

@media (max-width: 520px) {
  .app { margin: 16px; }
}

const STORAGE_KEY = 'todos';

const form = document.getElementById('todo-form');
const input = document.getElementById('todo-input');
const list = document.getElementById('todo-list');
const empty = document.getElementById('empty');

let todos = load();

function load() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
  } catch {
    return [];
  }
}

function save() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  } catch {
    // Storage unavailable (private mode, etc.): keep working in memory.
  }
}

function render() {
  list.replaceChildren(...todos.map(renderTodo));
  empty.hidden = todos.length > 0;
}

function renderTodo(todo) {
  const li = document.createElement('li');
  li.className = 'todo' + (todo.done ? ' done' : '');
  li.dataset.id = todo.id;

  const label = document.createElement('label');
  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.checked = todo.done;
  const text = document.createElement('span');
  text.textContent = todo.text;
  label.append(checkbox, text);

  const del = document.createElement('button');
  del.type = 'button';
  del.className = 'delete';
  del.textContent = '✕';
  del.setAttribute('aria-label', `Delete "${todo.text}"`);

  li.append(label, del);
  return li;
}

function update(next) {
  todos = next;
  save();
  render();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const text = input.value.trim();
  if (!text) return;
  update([...todos, { id: crypto.randomUUID(), text, done: false }]);
  input.value = '';
  input.focus();
});

list.addEventListener('change', (e) => {
  if (e.target.type !== 'checkbox') return;
  const id = e.target.closest('.todo').dataset.id;
  update(todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
});

list.addEventListener('click', (e) => {
  if (!e.target.classList.contains('delete')) return;
  const id = e.target.closest('.todo').dataset.id;
  update(todos.filter((t) => t.id !== id));
});

render();

